import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DMtjdCb-.js";const n="/help/assets/release-radar.en.BLdjl8Y3.png",r="/help/assets/resource-variants.en.BcbdNHhZ.png",i="/help/assets/torrent-results.en.RFKs0zCs.png",f=JSON.parse('{"title":"4. Subscribe and download","description":"","frontmatter":{},"headers":[],"relativePath":"en/subscribe.md","filePath":"en/subscribe.md"}'),l={name:"en/subscribe.md"};function d(c,e,h,p,u,g){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="_4-subscribe-and-download" tabindex="-1">4. Subscribe and download <a class="header-anchor" href="#_4-subscribe-and-download" aria-label="Permalink to &quot;4. Subscribe and download&quot;">​</a></h1><p>Choose a release, then subscribe or submit a download task. Ani-RSS subscriptions follow later episodes automatically; Torrent downloads submit the release you select now.</p><h2 id="find-the-title" tabindex="-1">Find the title <a class="header-anchor" href="#find-the-title" aria-label="Permalink to &quot;Find the title&quot;">​</a></h2><ol><li>Enter a title in <strong>Title / alias</strong>, or open <strong>Release radar</strong>.</li><li>In the radar, select its season and click the title to open details.</li><li>Check the <strong>Ani-RSS</strong> results; use resource search if you need fresh results.</li></ol><p><img src="'+n+'" alt="Release radar: seasonal titles and episode updates" loading="lazy"></p><p><strong>Sync</strong> retrieves subscription and media status already known to Ani-RSS. <strong>Search</strong> checks the season&#39;s titles one by one. The search runs in the background with progress shown on the page.</p><h2 id="choose-an-ani-rss-release" tabindex="-1">Choose an Ani-RSS release <a class="header-anchor" href="#choose-an-ani-rss-release" aria-label="Permalink to &quot;Choose an Ani-RSS release&quot;">​</a></h2><ol><li>Choose a release group.</li><li>If it offers several variants, use the dropdown to check subtitles, platform, and quality, such as simplified/traditional Chinese or Baha.</li><li>Select the release and choose <strong>Enable subscription</strong>. Check the group and variant on the confirmation page, then choose <strong>Enable subscription</strong> again.</li><li>Wait for <strong>Subscribed</strong>. Downloaded episodes appear in the title&#39;s playback area.</li></ol><p><img src="'+r+'" alt="Choose a group and its specific release variant" loading="lazy"></p><p><strong>Expected result:</strong> the title is subscribed and available media appears in Playback. Ani-RSS handles later episodes while AnimeMachine synchronizes the status.</p><p>Language or quality mismatch labels refer to your current preferences. If you want that variant anyway, choose the override action and review the mismatch before confirming.</p><h2 id="track-a-future-title-or-archive-release" tabindex="-1">Track a future title or archive release <a class="header-anchor" href="#track-a-future-title-or-archive-release" aria-label="Permalink to &quot;Track a future title or archive release&quot;">​</a></h2><p>Open <strong>Track releases</strong> in title details and choose <strong>Subscribe when available</strong>. The saved intent appears as <strong>Awaiting releases</strong>. Background checks enable an Ani-RSS subscription when a matching release becomes available. Your choice is kept while Ani-RSS is disconnected.</p><p>Tracking uses the release groups in Settings by default. To narrow the selection, clear that option and expand the group, for example <strong>Kirara Fantasia → Baha</strong> only. Existing Ani-RSS subscriptions keep their settings.</p><p>For BDRip and other collection editions, choose <strong>Track archive releases</strong>. Matching releases produce a notification; you choose whether to download. Open <strong>Track releases</strong> in Release radar to review, change, or stop tracking.</p><h2 id="choose-a-torrent-release" tabindex="-1">Choose a Torrent release <a class="header-anchor" href="#choose-a-torrent-release" aria-label="Permalink to &quot;Choose a Torrent release&quot;">​</a></h2><ol><li>Confirm qBittorrent is connected in <strong>Settings → Connections</strong>.</li><li>Choose <strong>Search torrents</strong> in title details and wait for results.</li><li>Expand <strong>Torrent</strong>, choose a group, then choose its subtitle and quality variant.</li><li>Choose <strong>Preview download plan</strong>, check the title, files, and destination, then submit.</li><li>Open qBittorrent, select the newly added stopped task, and start it.</li></ol><p><img src="'+i+'" alt="Expand Torrent results and select a group and variant" loading="lazy"></p><p>Local Torrent plans are added stopped; starting the task begins the transfer. Ongoing series are checked for season and episode continuity. Completed titles and films remain available for collection downloads.</p><p>For ongoing series with hundreds of episodes, each variant needs a continuous recent 24-episode window and may trail the latest release by one episode. It does not need the entire history in one search. Archive editions remain available for collecting older episodes in batches.</p><h2 id="use-your-own-torrent-pool" tabindex="-1">Use your own Torrent pool <a class="header-anchor" href="#use-your-own-torrent-pool" aria-label="Permalink to &quot;Use your own Torrent pool&quot;">​</a></h2><p>In <strong>Settings → Connections → Torrent Collector</strong>, title searches and the pool can work independently:</p><table tabindex="0"><thead><tr><th>Workflow</th><th>Configuration</th></tr></thead><tbody><tr><td>Find a release for one title</td><td>Choose <strong>Search Torrents</strong> in its details; no separate collector service is needed</td></tr><tr><td>Keep your own folder of <code>.torrent</code> files</td><td>Set <strong>Torrent pool path</strong> and enable <strong>Scan the pool on a schedule</strong></td></tr><tr><td>Add Torrents to the pool automatically</td><td>Deploy Torrent Collector with Compose and enable <strong>Collect Torrents automatically</strong></td></tr></tbody></table><p>For an existing pool, you can turn off automatic collection while keeping scheduled scans. All three workflows use the same release preferences and title-detail selection. Review the file list and destination before submitting a download.</p><h2 id="a-download-has-not-started" tabindex="-1">A download has not started <a class="header-anchor" href="#a-download-has-not-started" aria-label="Permalink to &quot;A download has not started&quot;">​</a></h2><p>Check connection and task status in AnimeMachine, then inspect the task and available seeds in qBittorrent. A submitted task waiting for peers differs from a download not yet submitted. Follow the <a href="./troubleshooting.html#download">download checks</a> in order.</p>',26)])])}const m=t(l,[["render",d]]);export{f as __pageData,m as default};
